CREATE DATABASE IF NOT EXISTS e_commerce_php CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE e_commerce_php;

CREATE TABLE IF NOT EXISTS category (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, description TEXT, parent_id BIGINT UNSIGNED NULL, FOREIGN KEY (parent_id) REFERENCES category(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS seller (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS supplier (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, contact_email VARCHAR(150), phone VARCHAR(30), status VARCHAR(30) DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT UNSIGNED NULL, supplier_id BIGINT UNSIGNED NULL, category_id BIGINT UNSIGNED NULL, name VARCHAR(200) NOT NULL, description TEXT, price DECIMAL(10,2) NOT NULL, quantity INT DEFAULT 0, sku VARCHAR(100) UNIQUE, status VARCHAR(30) DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (seller_id) REFERENCES seller(id) ON DELETE SET NULL, FOREIGN KEY (supplier_id) REFERENCES supplier(id) ON DELETE SET NULL, FOREIGN KEY (category_id) REFERENCES category(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS product_image (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, image_path TEXT NOT NULL, is_primary BOOLEAN DEFAULT FALSE, FOREIGN KEY (product_id) REFERENCES product(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS stock (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, supplier_id BIGINT UNSIGNED NULL, quantity INT DEFAULT 0, min_quantity INT DEFAULT 0, last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES product(id) ON DELETE CASCADE, FOREIGN KEY (supplier_id) REFERENCES supplier(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS buyer (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, phone VARCHAR(30), image_path TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wishlist (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, buyer_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_wishlist (buyer_id, product_id), FOREIGN KEY (buyer_id) REFERENCES buyer(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES product(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cart (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, buyer_id BIGINT UNSIGNED NULL, session_key VARCHAR(128) NULL, status VARCHAR(30) DEFAULT 'OPEN', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (buyer_id) REFERENCES buyer(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cart_item (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cart_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, FOREIGN KEY (cart_id) REFERENCES cart(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES product(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, buyer_id BIGINT UNSIGNED NULL, status VARCHAR(30) DEFAULT 'PENDING', total DECIMAL(10,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (buyer_id) REFERENCES buyer(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS order_item (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES product(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS payment (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method VARCHAR(40) NOT NULL, status VARCHAR(30) DEFAULT 'PENDING', FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS delivery (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, address TEXT NOT NULL, status VARCHAR(30) DEFAULT 'PREPARING', tracking_code VARCHAR(80), FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS review (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, buyer_id BIGINT UNSIGNED NULL, rating TINYINT NOT NULL, comment TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES product(id) ON DELETE CASCADE);

